#include <stdio.h>

/* teste do desafio saudacao-em-dois-mundos — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario captura o stdout DENTRO do teste: freopen manda o stdout para
   um arquivo proprio, o teste chama a funcao do aluno e le o arquivo de
   volta. O fflush descarrega SEM fechar — o stdout fica no estado legal para
   o freopen do cenario seguinte. */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
void saudacao(void);
void saudacaoEmDoisMundos(void);

SM_TEST(a_caixa_sozinha_imprime_uma_linha) {
    freopen("sm_saida_1.tmp", "w", stdout);
    saudacao();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha da caixa saudacao", linha, "bom dia, mundo\n",
              "a caixa saudacao existe e imprime a sua linha");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("a caixa nao imprime linha a mais", fim, "(nada impresso)",
              "uma chamada roda o corpo uma vez: uma linha, e acabou");
    fclose(f);
}

SM_TEST(duas_chamadas_duas_linhas) {
    freopen("sm_saida_2.tmp", "w", stdout);
    saudacaoEmDoisMundos();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a primeira saudacao", linha, "bom dia, mundo\n",
              "a primeira chamada roda o corpo da caixa");
    fgets(linha, 80, f);
    checa_str("a segunda saudacao", linha, "bom dia, mundo\n",
              "a segunda chamada roda o MESMO corpo outra vez");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha terceira linha", fim, "(nada impresso)",
              "sao duas chamadas: a saida acaba na segunda linha");
    fclose(f);
}

solutionCode:
#include <stdio.h>

void saudacao(void) {
    printf("bom dia, mundo\n");
}

void saudacaoEmDoisMundos(void) {
    saudacao();
    saudacao();
}
